/* Approved fraction tutorial. Local teaching state only; no saves or rewards. */
(()=>{ 'use strict';
const markup="<div id=\"dw-experiment\">\n<style>\n#dw-experiment{max-width:360px;margin:auto;font:14px/1.35 system-ui,sans-serif;color:#f3f6fc}\n#dw-experiment *{box-sizing:border-box}\n#dw-experiment [hidden]{display:none!important}\n#dw-experiment .game{position:relative;background:#0d1729;border:1px solid #405571;border-radius:16px;padding:10px;overflow:hidden}\n#dw-experiment header{display:flex;justify-content:space-between;align-items:center;gap:12px}\n#dw-experiment h2{margin:0;color:#ffda61;font-size:18px;line-height:1.3}\n#dw-experiment small{color:#b8cce2}\n#dw-experiment .coach{display:flex;gap:8px;align-items:center;margin:6px 0;min-height:56px}\n#dw-experiment .hero{width:42px;height:56px;object-fit:contain;flex-shrink:0}\n#dw-experiment .coach p{margin:0;line-height:1.45}\n#dw-experiment .controls{display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin-bottom:6px}\n#dw-experiment label{flex:1 1 110px}\n#dw-experiment select,#dw-experiment button{font:inherit;border:1px solid #5b7190;border-radius:10px;min-height:44px;padding:9px 12px;color:#f3f6fc;background:#233c57;cursor:pointer}\n#dw-experiment select{display:block;width:100%;margin-top:5px}\n#dw-experiment button:disabled{opacity:.5;cursor:default}\n#dw-experiment .gold{background:#ffda61;color:#172236;border-color:#ffda61;flex:1 1 140px}\n#dw-experiment .split{width:100%;margin-bottom:5px}\n#dw-experiment .hint{margin:0 0 6px;color:#bacfe5;font-size:12px;line-height:1.35}\n#dw-experiment .zone{background:#182c3d;border:1px solid #3f586c;border-radius:10px;padding:6px 8px;margin-top:6px}\n#dw-experiment .zone.ready{outline:2px dashed #ffda61}\n#dw-experiment .zone.over{background:#2b4a51;outline:3px solid #ffda61}\n#dw-experiment .zone-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:4px}\n#dw-experiment .value{color:#ffdd78;display:flex;gap:8px;align-items:center;white-space:nowrap}\n#dw-experiment .fraction{display:inline-flex;flex-direction:column;text-align:center;min-width:24px;line-height:1.2}\n#dw-experiment .fraction .num{border-bottom:1px solid currentColor;padding:0 3px 2px}\n#dw-experiment .fraction .den{padding-top:2px}\n#dw-experiment .board{position:relative;width:128px;max-width:100%;margin:0 auto;aspect-ratio:2/1;background:#0c1a27;border-radius:3px;overflow:visible}\n#dw-experiment .zones{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n#dw-experiment .zone{min-width:0;padding:6px}\n#dw-experiment .zone:first-child{grid-column:1/-1;position:relative}\n#dw-experiment .zone-head{font-size:12px;flex-wrap:wrap;min-height:34px}\n#dw-experiment .zone:first-child .zone-head{justify-content:center;gap:14px}\n#dw-experiment .stage-wira{position:absolute;width:48px;height:66px;object-fit:contain;left:8px;top:37px;pointer-events:none}\n#dw-experiment .cut .stage-wira{animation:dw-free-cut .55s ease-in-out}\n#dw-experiment .lesson-action{width:100%;margin-top:10px}\n#dw-experiment .choices{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n#dw-experiment .choices button{flex:1 1 85px}\n#dw-experiment .transfer{padding:12px 0}\n#dw-experiment .bar{display:flex;gap:2px;margin:16px 0}\n#dw-experiment .bar button{flex:1;min-width:0;height:55px;padding:0;border-radius:3px;background:#233c57}\n#dw-experiment .bar button[aria-pressed=\"true\"]{background:#ffda61;color:#172236}\n#dw-experiment .bar-label{text-align:center;color:#b8cce2;font-size:12px}\n#dw-experiment .coach{min-height:96px;align-items:center;background:#162338;border-radius:12px;padding:8px;margin:10px 0;gap:10px}\n#dw-experiment .coach .hero{width:44px;height:68px}\n#dw-experiment .teacher-name{color:#ffda61;font-size:12px;margin-bottom:4px}\n#dw-experiment .mode{font-size:12px;background:#203149;border-radius:20px;padding:5px 9px;white-space:nowrap}\n#dw-experiment .choices.explain{display:grid;grid-template-columns:1fr}\n#dw-experiment .interaction-note{margin:7px 0 0;color:#cfdeef;font-size:12px;min-height:32px}\n#dw-experiment select{font-size:16px}\n#dw-experiment .put:disabled{opacity:.55}\n#dw-experiment .put{padding:8px 4px;font-size:12px}\n#dw-experiment .piece:disabled{opacity:1;cursor:default}\n#dw-experiment .empty{position:absolute;inset:0;border:1px dashed #7794a6;pointer-events:none}\n#dw-experiment .piece{position:absolute;min-height:0;padding:0;border-radius:0;border:1px solid #183044;background-color:transparent;overflow:hidden;touch-action:none;cursor:grab}\n#dw-experiment .piece svg{display:block;width:100%;height:100%;pointer-events:none}\n#dw-experiment .piece.selected{outline:3px solid #ffdf72;z-index:3}\n#dw-experiment .piece.dragging{opacity:0;pointer-events:none}\n#dw-experiment .ghost{position:absolute;z-index:20;pointer-events:none;opacity:.95;box-shadow:0 8px 16px #0005;overflow:hidden}\n#dw-experiment .ghost svg{display:block;width:100%;height:100%}\n#dw-experiment .put{width:100%;margin-top:8px}\n#dw-experiment .summary{margin:6px 0 0;color:#bacfe5;font-size:12px;line-height:1.35}\n#dw-experiment .game{isolation:isolate;min-height:470px;padding-bottom:220px;background:radial-gradient(ellipse at top,#203d48,#0d1729 70%)}\n#dw-experiment header{position:relative;z-index:4;margin-bottom:12px}\n#dw-experiment .shade{position:absolute;inset:0;background:#03091699;z-index:2;pointer-events:none;display:none}\n#dw-experiment .teaching .shade{display:block}\n#dw-experiment .zone{position:relative;margin-top:0}\n#dw-experiment .spotlight{z-index:3;position:relative;box-shadow:0 0 0 2px #ffda61}\n#dw-experiment .transfer.spotlight{background:#16283d;border-radius:10px;padding:12px}\n#dw-experiment .tutorial{position:absolute;bottom:10px;left:10px;right:10px;z-index:5;background:#18283e;border:1px solid #cfb76f;border-radius:14px;padding:10px;box-shadow:0 8px 24px #0006}\n#dw-experiment .tutorial .coach{margin:0;padding:0;background:none;min-height:78px;align-items:center}\n#dw-experiment .tutorial .hero{height:78px;width:48px}\n#dw-experiment .tutorial .choices{margin-top:8px}\n#dw-experiment .interaction-note{position:relative;z-index:4;color:#e2eaf6}\n#dw-experiment .help{display:block;margin:0 0 10px auto;font-size:12px}\n#dw-experiment .challenge,#dw-experiment .close-help{width:100%;margin-top:8px}\n#dw-experiment .ghost{z-index:10}\n@keyframes dw-free-cut{0%,100%{transform:rotate(0)}40%{transform:translateX(15px) rotate(-12deg)}70%{transform:translateX(15px) rotate(12deg)}}\n@media(prefers-reduced-motion:reduce){#dw-experiment *{animation:none!important;transition:none!important}}\n#dw-experiment .finish{width:100%;margin-top:8px;background:#ffda61;color:#172236;position:relative;z-index:5}\n</style>\n<div class=\"game\">\n <header><h2>Dapur Wira</h2><small class=\"mode\">1 · Tengok</small></header>\n <button type=\"button\" class=\"help\" hidden>Tanya Cikgu</button>\n <div class=\"shade\" aria-hidden=\"true\"></div>\n <div class=\"controls\"><label>Bahagian sama besar<select aria-label=\"Bilangan bahagian sama besar\"><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option><option>7</option><option>8</option><option>9</option><option>10</option></select></label><button type=\"button\" class=\"gold new\">Wira, potong kek</button></div>\n <button type=\"button\" class=\"split\">Pecahkan setiap bahagian lagi</button>\n <p class=\"hint\">Semua potongan dibelah dua, termasuk yang di pinggan.</p>\n <div class=\"zones\"></div>\n <p class=\"interaction-note\" aria-live=\"polite\" hidden></p>\n <div class=\"transfer\" hidden></div>\n <div class=\"tutorial\" role=\"region\" aria-label=\"Bimbingan Cikgu Dimensi\">\n  <div class=\"coach\"><img class=\"hero\" alt=\"Cikgu Dimensi\"><div><div class=\"teacher-name\">Cikgu Dimensi</div><p class=\"message\" aria-live=\"polite\"></p></div></div>\n  <div class=\"choices\" hidden></div>\n  <button type=\"button\" class=\"gold lesson-action\"></button>\n  <button type=\"button\" class=\"close-help\" hidden>Sambung main</button>\n </div>\n <button type=\"button\" class=\"finish\" hidden>Sambung latihan</button>\n <button type=\"button\" class=\"challenge\" hidden>Cuba cabaran baharu</button>\n <p class=\"summary\">Atas: potongan di sini. Bawah: semua potongan sama besar daripada satu kek.</p>\n</div>\n\n</div>\n";
window.PAFractionLesson={mount(host,onComplete){
if(!host)return;host._fractionCleanup?.();host.innerHTML=markup;


 const root=host.querySelector('#dw-experiment'),game=root.querySelector('.game'),zones=root.querySelector('.zones'),message=root.querySelector('.message'),select=root.querySelector('select'),newButton=root.querySelector('.new'),splitButton=root.querySelector('.split'),hint=root.querySelector('.hint');
 const cakeAsset='data:image/webp;base64,';
 const heroAsset='data:image/webp;base64,';
 const coachAsset='data:image/webp;base64,';
 root.querySelector('.hero').src=coachAsset;
 const lessonButton=root.querySelector('.lesson-action');
 let lesson=0,barSelected=new Set(),helpOpen=false,completed=false;
 const tutorial=root.querySelector('.tutorial'),help=root.querySelector('.help'),closeHelp=root.querySelector('.close-help'),challenge=root.querySelector('.challenge');
 function fitTutorial(){game.style.paddingBottom=tutorial.hidden?'10px':(tutorial.offsetHeight+24)+'px'}
 const sizing=typeof ResizeObserver!=='undefined'?new ResizeObserver(fitTutorial):null;sizing?.observe(tutorial);
 help.addEventListener('click',()=>{if(lesson!==7)return;helpOpen=true;render();message.textContent='Tarik kek ke pinggan. Nombor atas mengira potongan di situ. Nombor bawah mengira semua potongan daripada satu kek.';fitTutorial()});
 closeHelp.addEventListener('click',()=>{helpOpen=false;render()});
 challenge.addEventListener('click',()=>{if(lesson===7)lessonButton.click()});
 const choices=root.querySelector('.choices'),transfer=root.querySelector('.transfer');
 const lessons=[
 'Ini satu kek penuh. Jom lihat Wira potong dua sama besar.',
 'Arif ambil 1 daripada 2 potongan sama besar. Pecahan mana yang betul?',
 'Beri Arif separuh kek. Tarik satu potongan ke pinggan Arif.',
 'Arif dapat 1/2, iaitu separuh kek. Jom belah setiap potongan dua lagi.',
 '1/2 menjadi 2/4. Kenapa jumlah kek Arif masih sama?',
 'Jadikan kek Arif penuh semula. Tarik baki dua potongan kepada Arif.',
 '4/4 = 1 kek penuh! Semua empat potongan sudah berkumpul. Jom cuba sendiri.',
 'Jom main! Agihkan kek ke pinggan. Potong lagi dan lihat nombor berubah.',
 'Beri Aurora 3/4 kek. Kira sendiri, kemudian tekan “Semak”.',
 'Betul! Aurora dapat 3 daripada 4 potongan, iaitu 3/4 kek. Jom main bebas!',
 'Jalur ini ada 6 bahagian sama besar. Tekan bahagian untuk warnakan 2/3 jalur.',
 'Betul! 4/6 = 2/3. Walaupun bentuk berubah, pecahannya tetap sama.'
 ];
 const names=['Dulang asal','Pinggan Arif','Pinggan Aurora'];
 let pieces=partition(1),selected=null,drag=null,ghost=null,ignoreClick=false,cutTimer=null;
 function partition(n){
   const cols=n===9?3:n>2&&n%2===0?n/2:n,rows=n/cols;
   return Array.from({length:n},(_,i)=>({id:i,x:(i%cols)/cols,y:Math.floor(i/cols)/rows,w:1/cols,h:1/rows,zone:0}));
 }
 function refine(list){
   if(list.length*2>10)return list;
   return list.flatMap((p,i)=>2*p.w>=p.h?
    [{...p,id:i*2,w:p.w/2},{...p,id:i*2+1,x:p.x+p.w/2,w:p.w/2}]:
    [{...p,id:i*2,h:p.h/2},{...p,id:i*2+1,y:p.y+p.h/2,h:p.h/2}]);
 }
 function count(z,list=pieces){return list.filter(p=>p.zone===z).length}
 function gcd(a,b){while(b){const t=b;b=a%b;a=t}return a}
 function fraction(k,n){const g=gcd(k,n);return `${k}/${n}`+(k===n?' = 1':k>0&&g>1?` = ${k/g}/${n/g}`:'')}
 function art(p){return `<svg viewBox="${p.x*600} ${p.y*300} ${p.w*600} ${p.h*300}" preserveAspectRatio="none" aria-hidden="true"><image href="${cakeAsset}" width="600" height="300" preserveAspectRatio="none"/></svg>`}
 function render(){
   const n=pieces.length;
   root.querySelector('.finish').hidden=!completed||lesson!==7;
   const free=lesson===7,interactive=free||lesson===2||lesson===5||lesson===8;
   tutorial.hidden=free&&!helpOpen;help.hidden=!free;closeHelp.hidden=!(free&&helpOpen);challenge.hidden=!free;
   game.classList.toggle('teaching',!free||helpOpen);
   const note=root.querySelector('.interaction-note');note.hidden=!interactive;
   note.textContent=selected===null?'Tarik potongan ke pinggan. Atau tekan potongan dahulu.':'Potongan dipilih. Tekan “Letak di sini” pada pinggan.';
   choices.classList.toggle('explain',lesson===4);
   root.querySelector('.controls').hidden=!free;splitButton.hidden=!free;hint.hidden=!free;
   root.querySelector('.summary').hidden=!free;
   root.querySelector('.mode').textContent=free?'Main bebas':lesson>=10?'Cabaran baharu':lesson>=8?'Cuba sendiri':lesson<2?'Jom belajar':'Cuba bersama';
   lessonButton.hidden=free||[1,2,4,5].includes(lesson);
   lessonButton.textContent=({0:'Wira, potong dua',3:'Wira, potong lagi',6:'Saya nak cuba',7:'Cuba cabaran baharu',8:'Semak',9:'Jom main bebas',10:'Semak',11:'Main kek semula'})[lesson]||'';
   choices.hidden=![1,4].includes(lesson);choices.innerHTML='';
   if(lesson===1)choices.innerHTML=['1/2','2/1','1'].map(v=>`<button type="button" data-answer="${v}">${v}</button>`).join('');
   if(lesson===4)choices.innerHTML='<button type="button" data-answer="more">Kek Arif sudah bertambah.</button><button type="button" data-answer="same">Kek yang sama, cuma potongannya lebih kecil.</button>';
   zones.hidden=lesson>=10;transfer.hidden=lesson<10;
   if(lesson>=10){transfer.innerHTML=`<div class="bar-label">Satu jalur penuh</div><div class="bar">${Array.from({length:6},(_,i)=>`<button type="button" data-cell="${i}" aria-label="Bahagian ${i+1} daripada 6" aria-pressed="${barSelected.has(i)}" ${lesson===11?'disabled':''}>${barSelected.has(i)?'✓':''}</button>`).join('')}</div><div class="bar-label">${lesson===11?'4/6 = 2/3':'Tekan petak untuk warna. Tekan lagi untuk padam.'}</div>`;}
   splitButton.disabled=n*2>10;splitButton.textContent=n*2<=10?`Pecahkan lagi: ${n} → ${n*2} bahagian`:'Had 10 bahagian — cuba kek baharu';
   hint.textContent=n*2<=10?'Semua potongan dibelah dua. Banyak kek tetap sama.':'Maksimum 10 bahagian. Mula dengan kek baharu untuk potong lagi.';
   newButton.textContent=n===1?'Wira, potong kek':'Kek baharu & potong';
   zones.innerHTML=names.map((name,z)=>{
     const k=count(z),g=gcd(k,n),simple=k===n?' = 1':k>0&&g>1?` = ${k/g}/${n/g}`:'';
     const contents=pieces.filter(p=>p.zone===z).map(p=>`<button type="button" ${interactive?'':'disabled'} class="piece${p.id===selected?' selected':''}" data-piece="${p.id}" aria-pressed="${p.id===selected}" aria-label="Pilih potongan ${p.id+1}, satu daripada ${n}, di ${name}" style="left:${p.x*100}%;top:${p.y*100}%;width:${p.w*100}%;height:${p.h*100}%">${art(p)}</button>`).join('');
     return `<section class="zone${selected!==null?' ready':''}" data-zone="${z}" aria-label="${name}"><div class="zone-head"><span>${name}</span><span class="value" aria-label="${fraction(k,n)}"><span class="fraction"><span class="num">${k}</span><span class="den">${n}</span></span>${simple}</span></div><div class="board"><div class="empty"></div>${contents}</div><button type="button" class="put" data-put="${z}" ${!interactive?'hidden':selected===null?'disabled':''}>${z===0?'Pulangkan ke dulang':'Letak di sini'}</button></section>`;
   }).join('');
   zones.querySelector('.zone').insertAdjacentHTML('beforeend',`<img class="stage-wira" src="${heroAsset}" alt="Wira">`);
   if(lesson===8)zones.querySelectorAll('.value').forEach(e=>{e.textContent='?';e.setAttribute('aria-label','Kiraan disembunyikan semasa cabaran')});
   const focusZones=lesson<=1?[0]:[2,5].includes(lesson)?[0,1]:[3,4,6].includes(lesson)?[1]:lesson===8?[0,2]:lesson===9?[2]:[];
   zones.querySelectorAll('.zone').forEach((el,i)=>el.classList.toggle('spotlight',focusZones.includes(i)));
   transfer.classList.toggle('spotlight',lesson>=10);
   fitTutorial();
 }
 choices.addEventListener('click',e=>{
   const b=e.target.closest('[data-answer]');if(!b)return;const a=b.dataset.answer;
   if(lesson===1){if(a!=='1/2'){message.textContent=a==='2/1'?'Nombor atas ialah bahagian diambil. Nombor bawah ialah semua bahagian sama besar. Cuba lagi.':'Satu kek penuh memerlukan kedua-dua potongan. Arif hanya ambil satu. Cuba lagi.';return}lesson=2;render();message.textContent='Ya, 1/2 ialah separuh. Tarik satu potongan ke pinggan Arif.';}
   else if(lesson===4){if(a!=='same'){message.textContent='Lihat kek Arif. Potongannya lebih kecil, tetapi tiada kek ditambah. Cuba lagi.';return}lesson=5;render();message.textContent=lessons[lesson];}
 });
 transfer.addEventListener('click',e=>{if(lesson!==10)return;const b=e.target.closest('[data-cell]');if(!b)return;const i=Number(b.dataset.cell);barSelected.has(i)?barSelected.delete(i):barSelected.add(i);render();message.textContent=lessons[10];});
 lessonButton.addEventListener('click',()=>{
   if(drag)return;
   if(lesson===0){pieces=partition(2);lesson=1;cutMotion()}
   else if(lesson===3){pieces=refine(pieces);lesson=4;cutMotion()}
   else if(lesson===6){lesson=8;pieces=partition(4)}
   else if(lesson===8){if(count(2)!==3){message.textContent='Belum tepat. Aurora mahu 3 daripada 4 potongan. Tambah atau pulangkan potongan, kemudian cuba lagi.';return}lesson=9}
   else if(lesson===9)lesson=7;
   else if(lesson===7){lesson=10;barSelected=new Set()}
   else if(lesson===10){if(barSelected.size!==4){message.textContent='Cuba lagi. Bahagikan 6 petak kepada 3 kumpulan sama besar. Warnakan 2 kumpulan.';return}lesson=11;completed=true}
   else if(lesson===11)lesson=7;
   else return;
   selected=null;render();message.textContent=lessons[lesson];
 });
 function move(id,z){
   if(![2,5,7,8].includes(lesson))return;
   if([2,5].includes(lesson)&&z!==1){message.textContent='Kali ini, beri kek kepada Arif dahulu.';return}
   const p=pieces.find(p=>p.id===id);if(!p||![0,1,2].includes(z))return;
   if(p.zone===z){selected=null;render();return}
   p.zone=z;selected=null;
   if(lesson===2&&count(1)===1)lesson=3;
   if(lesson===5&&count(1)===4)lesson=6;
   render();message.textContent=lesson===7?`${names[z]}: ${fraction(count(z),pieces.length)} kek. Cuba pindah atau potong lagi!`:lessons[lesson];
 }
 function cutMotion(){game.classList.remove('cut');void game.offsetWidth;game.classList.add('cut');clearTimeout(cutTimer);cutTimer=setTimeout(()=>game.classList.remove('cut'),600)}
 newButton.addEventListener('click',()=>{
   if(drag||lesson!==7)return;const n=Number(select.value);if(!Number.isInteger(n)||n<2||n>10)return;
   pieces=partition(n);selected=null;render();cutMotion();message.textContent=`Ini kek baharu dengan ${n} potongan sama besar. Jom agihkan!`;
 });
 splitButton.addEventListener('click',()=>{
   if(drag||lesson!==7||pieces.length*2>10)return;
   const old=pieces.length,before=names.map((_,z)=>count(z));pieces=refine(pieces);selected=null;render();cutMotion();
   const z=before[1]?1:before[2]?2:0;
   message.textContent=`${names[z]}: ${before[z]}/${old} → ${count(z)}/${pieces.length}. Potongan lebih kecil, banyak kek tetap sama!`;
 });
 zones.addEventListener('click',e=>{
   if(![2,5,7,8].includes(lesson))return;
   if(ignoreClick){ignoreClick=false;return}
   const b=e.target.closest('[data-piece]');if(b){const id=Number(b.dataset.piece);selected=selected===id?null:id;render();message.textContent=lessons[lesson];return}
   const put=e.target.closest('[data-put]');if(put&&selected!==null)move(selected,Number(put.dataset.put));
 });
 zones.addEventListener('pointerdown',e=>{
   if(drag||e.button!==0||![2,5,7,8].includes(lesson))return;const b=e.target.closest('[data-piece]');if(!b)return;
   const p=pieces.find(p=>p.id===Number(b.dataset.piece));const rect=b.getBoundingClientRect();
   drag={id:p.id,pointer:e.pointerId,startX:e.clientX,startY:e.clientY,offsetX:e.clientX-rect.left,offsetY:e.clientY-rect.top,width:rect.width,height:rect.height,active:false,button:b};
   zones.setPointerCapture(e.pointerId);
 });
 zones.addEventListener('pointermove',e=>{
   if(!drag||e.pointerId!==drag.pointer)return;
   if(!drag.active&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<6)return;
   if(!drag.active){drag.active=true;drag.button.classList.add('dragging');ghost=document.createElement('div');ghost.className='ghost';ghost.innerHTML=art(pieces.find(p=>p.id===drag.id));ghost.style.width=drag.width+'px';ghost.style.height=drag.height+'px';game.appendChild(ghost)}
   const rect=game.getBoundingClientRect();ghost.style.left=(e.clientX-rect.left-drag.offsetX)+'px';ghost.style.top=(e.clientY-rect.top-drag.offsetY)+'px';
   const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-zone]');zones.querySelectorAll('.zone').forEach(z=>z.classList.toggle('over',z===hit));
 });
 function finish(e,cancel=false){
   if(!drag||e.pointerId!==drag.pointer)return;const d=drag;drag=null;
   if(zones.hasPointerCapture(e.pointerId))zones.releasePointerCapture(e.pointerId);
   ghost?.remove();ghost=null;d.button.classList.remove('dragging');zones.querySelectorAll('.zone').forEach(z=>z.classList.remove('over'));
   if(!d.active&&!cancel){selected=selected===d.id?null:d.id;ignoreClick=true;render();message.textContent=lessons[lesson];setTimeout(()=>{ignoreClick=false},0);return}
   if(d.active){ignoreClick=true;setTimeout(()=>{ignoreClick=false},0);const target=cancel?null:document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-zone]');
     if(target&&root.contains(target))move(d.id,Number(target.dataset.zone));else message.textContent='Lepaskan potongan di pinggan atau dulang. Cuba lagi.';
   }
 }
 zones.addEventListener('pointerup',e=>finish(e));zones.addEventListener('pointercancel',e=>finish(e,true));
 root.querySelector('.finish').addEventListener('click',()=>{if(completed&&lesson===7&&host.isConnected)onComplete?.()});
 const cleanup=()=>{clearTimeout(cutTimer);sizing?.disconnect();detached?.disconnect();ghost?.remove()};
 const detached=typeof MutationObserver!=='undefined'?new MutationObserver(()=>{if(!host.isConnected)cleanup()}):null;
 detached?.observe(document.body,{childList:true,subtree:true});
 host._fractionCleanup=cleanup;
 render();
 message.textContent=lessons[lesson];

}};
})();
